<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class Pembayaran extends Model { public $timestamps=false; protected $table='pembayaran'; protected $primaryKey='id_pembayaran'; protected $guarded=['id_pembayaran','kode_pembayaran','id_transaksi','arah','status']; protected static function booted():void{static::creating(function(self $payment):void{if($payment->arah==='masuk'&&$payment->id_transaksi)app(\App\Services\GatewayPaymentGuard::class)->assertManualAllowed(Transaksi::findOrFail($payment->id_transaksi));});static::updating(function(self $payment):void{if($payment->isDirty('status')&&$payment->status==='terverifikasi'&&$payment->arah==='masuk'&&$payment->id_transaksi)app(\App\Services\GatewayPaymentGuard::class)->assertManualAllowed(Transaksi::findOrFail($payment->id_transaksi));});} protected function casts():array{return ['tanggal'=>'datetime','jumlah'=>'decimal:2','created_at'=>'datetime','verified_at'=>'datetime'];} public function transaksi(){return $this->belongsTo(Transaksi::class,'id_transaksi','id_transaksi');} }
